	ccBA: { en: 'Looking back: <b>{p}%</b> of its landmarks are historical, religious and cultural sites.', ar: 'نظرة إلى الماضي: <b>{p}%</b> من معالمه مواقع تاريخية ودينية وثقافية.' },
	ccR: { en: 'Heritage and institutions: <b>{a}</b> Roman and Punic sites, and <b>{b}</b> cultural or state institutions.', ar: 'التراث والمؤسسات: <b>{a}</b> مواقع رومانية وبونية، و<b>{b}</b> مؤسسات ثقافية أو رسمية.' },
